# Omegawiki, the Ultimate online dictionary

class Family(family.Family):

    def __init__(self):
        family.Family.__init__(self)
        self.name = 'omegawiki'
        self.langs['omegawiki'] = 'www.omegawiki.org'

        # On most Wikipedias page names must start with a capital letter, but some
        # languages don't use this.

        self.nocapitalize = self.langs.keys()

    def hostname(self,code):
        return 'www.omegawiki.org'

    def version(self, code):
        return "1.16alpha"

    def scriptpath(self, code):
        return ''

    def path(self, code):
        return '/index.php'

    def apipath(self, code):
        return '/api.php'

import logging
import os
from typing import Generic, List, Type, Any

import torch
import torch.nn as nn

from ..downloading.downloading_utils import from_cache
from ..featurization.featurization_api import T_BatchEncoding, T_Config, PretrainedFeaturizerMixin


class PretrainedModelBase(nn.Module, Generic[T_BatchEncoding, T_Config]):
    def __init__(self, config: T_Config):
        super().__init__()
        self.config = config

    def forward(self, batch: T_BatchEncoding):
        raise NotImplementedError

    @classmethod
    def _get_archive_dict(cls) -> dict:
        raise NotImplementedError

    @classmethod
    def get_config_cls(cls) -> Type[T_Config]:
        raise NotImplementedError

    @classmethod
    def get_featurizer_cls(cls) -> Type[PretrainedFeaturizerMixin[Any, T_BatchEncoding, T_Config]]:
        raise NotImplementedError

    @classmethod
    def from_pretrained(cls,
                        pretrained_name: str, *,
                        excluded: List[str] = None,
                        config: T_Config = None) -> "PretrainedModelBase[T_BatchEncoding, T_Config]":
        archive_dict = cls._get_archive_dict()
        file_path = from_cache(pretrained_name, archive_dict, 'pt')
        if not file_path:
            file_path = os.path.expanduser(pretrained_name)
            if not os.path.exists(file_path):
                raise FileNotFoundError(file_path)
            if not config:
                raise AttributeError('Set \'config\' attribute when using local path to weights.')
        if not config:
            config_cls = cls.get_config_cls()
            config = config_cls.from_pretrained(pretrained_name)
        model = cls(config)
        model.load_weights(file_path, excluded=excluded)
        return model

    def init_weights(self, init_type: str):
        for p in self.parameters():
            if p.dim() > 1:
                if init_type == 'uniform':
                    nn.init.xavier_uniform_(p)
                elif init_type == 'normal':
                    nn.init.xavier_normal_(p)
                else:
                    raise NotImplementedError()

    def _remove_excluded(self, dictionary: dict, *, excluded: List[str] = None):
        excluded = excluded if excluded else []
        return {k: v for k, v in dictionary.items() if all(k.split('.')[0] != p for p in excluded)}

    def load_weights(self, file_path: str, *, excluded: List[str] = None):
        state_dict = torch.load(file_path, map_location='cpu')
        state_dict = self._remove_excluded(state_dict, excluded=excluded)
        result = self.load_state_dict(state_dict, strict=False)
        if len(result.missing_keys) > 0:
            logging.info(f'Missing keys when loading: {result.missing_keys}')
        if len(result.unexpected_keys) > 0:
            logging.warning(f'Unexpected keys when loading: {result.unexpected_keys}')

    def save_weights(self, file_path: str, *, excluded: List[str] = None):
        state_dict = self.state_dict()
        state_dict = self._remove_excluded(state_dict, excluded=excluded)
        torch.save(state_dict, file_path)

#!/usr/bin/env python
import os
import json
import unittest
from collections import OrderedDict

from spdown.config import Config

TEST_CONFIG_PATHS = OrderedDict([
    ('local', 'config.json'),
    ('home', os.path.join(
        os.path.expanduser('~'), '.config',
        'spdown', 'config'
    ))
])

TEST_CONFIG = {
    'download_directory': '~/TestMusic'
}


class TestConfig(unittest.TestCase):
    @staticmethod
    def get_backup_path(config_location):
        return '{}.bak'.format(
            TEST_CONFIG_PATHS[config_location]
        )

    @staticmethod
    def backup_configuration(config_location):
        backup_path = TestConfig.get_backup_path(config_location)

        if os.path.exists(TEST_CONFIG_PATHS[config_location]):
            os.rename(
                TEST_CONFIG_PATHS[config_location],
                backup_path
            )

    @staticmethod
    def restore_configuration(config_location):
        backup_path = TestConfig.get_backup_path(config_location)

        if os.path.exists(backup_path):
            os.rename(
                backup_path,
                TEST_CONFIG_PATHS[config_location]
            )

    @staticmethod
    def create_test_config(config_location):
        TestConfig.backup_configuration(config_location)

        with open(TEST_CONFIG_PATHS[config_location], 'w') as f:
            json.dump(TEST_CONFIG, f)

    def test_find_configuration_file(self):
        config = Config()

        for config_path in TEST_CONFIG_PATHS.keys():
            TestConfig.backup_configuration(config_path)

        for config_path in TEST_CONFIG_PATHS.keys():
            config.set_config_path(None)
            TestConfig.create_test_config(config_path)
            config._load(exit_on_error=False)
            TestConfig.restore_configuration(config_path)
            self.assertEqual(TEST_CONFIG, config._configuration)

    def test_get(self):
        config = Config()

        for config_path in TEST_CONFIG_PATHS.keys():
            TestConfig.backup_configuration(config_path)

        for config_path in TEST_CONFIG_PATHS.keys():
            config.set_config_path(None)
            TestConfig.create_test_config(config_path)
            download_directory = config.get('download_directory')
            TestConfig.restore_configuration(config_path)
            self.assertEqual(download_directory, TEST_CONFIG['download_directory'])

    def test_set(self):
        config = Config()

        for config_path in TEST_CONFIG_PATHS.keys():
            TestConfig.backup_configuration(config_path)

        for config_path in TEST_CONFIG_PATHS.keys():
            config.set_config_path(None)
            TestConfig.create_test_config(config_path)
            config.set('download_directory', 'test')
            TestConfig.restore_configuration(config_path)
            self.assertEqual(config.get('download_directory'), 'test')

    def test_fix_path_errors(self):
        config = Config()

        for config_path in TEST_CONFIG_PATHS.keys():
            TestConfig.backup_configuration(config_path)

        for config_path in TEST_CONFIG_PATHS.keys():
            config.set_config_path(None)
            TestConfig.create_test_config(config_path)
            config.set('download_directory', '~/Music/')
            config._configuration = None
            self.assertEqual(config.get('download_directory'), '~/Music')
            TestConfig.restore_configuration(config_path)


if __name__ == "__main__":
    unittest.main()
